import React from 'react';
import styled from 'styled-components';
import { devices } from '../styles/breakpoints';
import Banner from '../components/common/Banner';
import { appBannerItems } from '../data/products';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;

  ${devices.desktop} {
    padding-top: 80px;
  }
`;

const ImageSection = styled.section`


`;

const App: React.FC = () => {

  return (
    <PageWrapper>
      <Banner
        bannerGroups={appBannerItems}
        autoplay={false}
        showArrows={false}
      />
      <ImageSection>
        <img src="/images/App/app_image_1.png" alt="App Image 1" />
        <img src="/images/App/app_image_2.jpg" alt="App Image 2" />
        <img src="/images/App/app_image_3.png" alt="App Image 3" />
      </ImageSection> 
    </PageWrapper>
  );
};

export default App; 