const Copyright = styled.div`
  font-size: 10px;
  color: #999;
  
  ${devices.tablet} {
    font-size: 11px;
  }

  ${devices.desktop} {
    font-size: 12px;
  }
`;

const LoadingCard = styled(ManualCard)`
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  
  .loading-text {
    color: #666;
    font-size: 14px;
    
    ${devices.tablet} {
      font-size: 16px;
    }
    
    ${devices.desktop} {
      font-size: 18px;
    }
  }
`;

const ErrorCard = styled(ManualCard)`
  .error-title {
    color: #e74c3c;
    font-size: 18px;
    font-weight: 600;
    margin-bottom: 10px;
    
    ${devices.tablet} {
      font-size: 20px;
    }
    
    ${devices.desktop} {
      font-size: 22px;
    }
  }
  
  .error-message {
    color: #666;
    font-size: 14px;
    margin-bottom: 20px;
    
    ${devices.tablet} {
      font-size: 15px;
    }
    
    ${devices.desktop} {
      font-size: 16px;
    }
  }
  
  .error-button {
    background: #007bff;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.3s ease;
    
    &:hover {
      background: #0056b3;
    }
    
    ${devices.tablet} {
      padding: 12px 24px;
      font-size: 15px;
    }
    
    ${devices.desktop} {
      padding: 14px 28px;
      font-size: 16px;
    }
  }
`;

const NewManual: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  
  const [productData, setProductData] = useState<ProductManualData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadProductData = async () => {
      if (!id) {
        setError('产品ID缺失');
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError(null);
        const data = await fetchProductManualData(id);
        setProductData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : '加载失败');
      } finally {
        setLoading(false);
      }
    };

    loadProductData();
  }, [id]);

  const handleLanguageClick = (language: ManualLanguage) => {
    // 这里可以添加下载或跳转逻辑
    console.log(`Selected language: ${language.name}`);
    // 打开手册链接
    window.open(language.url, '_blank');
  };

  const handleRetry = () => {
    if (id) {
      const loadProductData = async () => {
        try {
          setLoading(true);
          setError(null);
          const data = await fetchProductManualData(id);
          setProductData(data);
        } catch (err) {
          setError(err instanceof Error ? err.message : '加载失败');
        } finally {
          setLoading(false);
        }
      };
      loadProductData();
    }
  };

  const handleGoBack = () => {
    navigate(-1);
  };

  const handleContactClick = () => {
    const email = 'service@ovutek.com';
    const subject = '语言支持咨询';
    const body = '您好，我需要其他语言版本的产品手册，请协助提供。\n\n谢谢！';
    
    const mailtoUrl = `mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailtoUrl;
  };

  // 渲染Loading状态
  if (loading) {
    return (
      <PageWrapper>
        <LoadingCard>
          <div className="loading-text">加载中...</div>
        </LoadingCard>
      </PageWrapper>
    );
  }

  // 渲染Error状态
  if (error) {
    return (
      <PageWrapper>
        <ErrorCard>
          <div className="error-title">加载失败</div>
          <div className="error-message">{error}</div>
          <div>
            <button className="error-button" onClick={handleRetry}>
              重试
            </button>
            {' '}
            <button className="error-button" onClick={handleGoBack}>
              返回
            </button>
          </div>
        </ErrorCard>
      </PageWrapper>
    );
  }

  // 渲染成功状态
  if (!productData) {
    return null;
  }

  return (
    <PageWrapper>
      <ManualCard>
        <Logo>
          <img src="/images/logo.png" alt="Ovutek" />
        </Logo>

        <ProductTitle>{productData.title}</ProductTitle>
        <ProductModel>{productData.model}</ProductModel>

        <ManualTitle>User Manual</ManualTitle>

        <LanguageList>
          {productData.languages.map((language, index) => (
            <LanguageItem
              key={index}
              onClick={() => handleLanguageClick(language)}
            >
              {language.name}
            </LanguageItem>
          ))}
        </LanguageList>

        <ContactSection>
          <ContactText>Can't find your language? Contact Us:</ContactText>
          <ContactEmail onClick={handleContactClick}>
            service@ovutek.com
          </ContactEmail>
        </ContactSection>

        <Copyright>
          © 2025 OVUTEK. All rights reserved.
        </Copyright>
      </ManualCard>
    </PageWrapper>
  );
};

export default NewManual; 