import React from 'react';
import styled from 'styled-components';
import { devices } from '../styles/breakpoints';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;

  ${devices.desktop} {
    padding-top: 80px;
  }
`;

const ContentWrapper = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 20px 80px;

  ${devices.desktop} {
    padding: 80px 20px 120px;
  }
`;

const PageHeader = styled.header`
  text-align: center;
  margin-bottom: 60px;

  ${devices.desktop} {
    margin-bottom: 80px;
  }

  h1 {
    font-size: 28px;
    font-weight: 400;
    color: #000;
    margin-bottom: 16px;

    ${devices.desktop} {
      font-size: 42px;
      margin-bottom: 24px;
    }
  }

  .subtitle {
    font-size: 16px;
    color: #666;
    line-height: 1.6;

    ${devices.desktop} {
      font-size: 18px;
    }
  }
`;

const ContentSection = styled.section`
  background: #ffffff;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  margin-bottom: 40px;

  ${devices.desktop} {
    padding: 60px;
    margin-bottom: 60px;
  }

  h2 {
    font-size: 20px;
    font-weight: 500;
    color: #000;
    margin-bottom: 24px;

    ${devices.desktop} {
      font-size: 24px;
      margin-bottom: 32px;
    }
  }

  h3 {
    font-size: 18px;
    font-weight: 500;
    color: #333;
    margin-bottom: 16px;
    margin-top: 32px;

    ${devices.desktop} {
      font-size: 20px;
      margin-bottom: 20px;
      margin-top: 40px;
    }
  }

  p {
    font-size: 14px;
    color: #666;
    line-height: 1.8;
    margin-bottom: 16px;

    ${devices.desktop} {
      font-size: 16px;
      margin-bottom: 20px;
    }
  }

  ul, ol {
    padding-left: 20px;
    margin-bottom: 16px;

    ${devices.desktop} {
      margin-bottom: 20px;
    }

    li {
      font-size: 14px;
      color: #666;
      line-height: 1.8;
      margin-bottom: 8px;

      ${devices.desktop} {
        font-size: 16px;
        margin-bottom: 12px;
      }
    }
  }

  .highlight {
    background: #f0f9ff;
    border-left: 4px solid #0ea5e9;
    padding: 16px 20px;
    margin: 20px 0;
    border-radius: 0 8px 8px 0;

    p {
      margin: 0;
      font-weight: 500;
      color: #0c4a6e;
    }
  }
`;

const LastUpdated = styled.div`
  text-align: center;
  padding: 20px;
  background: #f8f9fa;
  border-radius: 8px;
  margin-top: 40px;

  p {
    font-size: 14px;
    color: #666;
    margin: 0;

    ${devices.desktop} {
      font-size: 16px;
    }
  }
`;

const TableOfContents = styled.div`
  background: #f8f9fa;
  border-radius: 12px;
  padding: 30px;
  margin-bottom: 40px;

  ${devices.desktop} {
    padding: 40px;
    margin-bottom: 60px;
  }

  h3 {
    font-size: 18px;
    font-weight: 500;
    color: #000;
    margin-bottom: 20px;

    ${devices.desktop} {
      font-size: 20px;
      margin-bottom: 24px;
    }
  }

  ul {
    list-style: none;
    padding: 0;
    margin: 0;

    li {
      margin-bottom: 8px;

      a {
        color: #0ea5e9;
        text-decoration: none;
        font-size: 14px;
        line-height: 1.6;

        ${devices.desktop} {
          font-size: 16px;
        }

        &:hover {
          text-decoration: underline;
        }
      }
    }
  }
`;

