// 统一的分析和事件追踪工具

// 确保gtag全局函数可用
declare global {
  interface Window {
    gtag: (...args: any[]) => void;
  }
}

// 事件参数接口
interface EventParams {
  product_id?: string;
  product_name?: string;
  category?: string;
  price?: string;
  color?: string;
  url?: string;
  source?: string;
  [key: string]: any;
}

// 分析工具类
class Analytics {
  // 发送自定义事件到Google Analytics
  private sendEvent(eventName: string, params: EventParams = {}) {
    try {
      if (typeof window !== 'undefined' && window.gtag) {
        window.gtag('event', eventName, {
          event_category: 'user_interaction',
          event_label: params.product_name || 'unknown',
          value: params.price ? parseFloat(params.price.replace(/[^0-9.]/g, '')) : undefined,
          custom_map: {
            product_id: params.product_id,
            color: params.color,
            source: params.source,
          },
          ...params
        });
        
        // 同时在控制台输出，方便调试
        console.log(`📊 Analytics Event: ${eventName}`, params);
      } else {
        console.warn('Google Analytics (gtag) not available');
      }
    } catch (error) {
      console.error('Analytics event error:', error);
    }
  }

  // 自定义的gotobuy事件
  gotobuy(params: {
    product_id?: string;
    product_name?: string;
    category?: string;
    price?: string;
    color?: string;
    url?: string;
    source?: string; // 来源页面
  }) {
    this.sendEvent('gotobuy', {
      event_category: 'purchase_intent',
      event_label: `${params.product_name || 'unknown'} - ${params.color || 'default'}`,
      ...params
    });

    // 额外的本地统计（可以后续扩展到后端API）
    this.logToLocal('gotobuy', params);
  }

  // 产品点击事件
  productClick(params: {
    product_id?: string;
    product_name?: string;
    category?: string;
    source?: string;
  }) {
    this.sendEvent('product_click', {
      event_category: 'product_interaction',
      ...params
    });
  }

  // 颜色切换事件
  colorChange(params: {
    product_id?: string;
    product_name?: string;
    from_color?: string;
    to_color?: string;
  }) {
    this.sendEvent('color_change', {
      event_category: 'product_interaction',
      event_label: `${params.from_color} -> ${params.to_color}`,
      ...params
    });
  }

  // 页面浏览事件
  pageView(pageName: string, additionalParams: EventParams = {}) {
    this.sendEvent('page_view', {
      event_category: 'navigation',
      page_title: pageName,
      ...additionalParams
    });
  }

  // 本地日志记录（用于调试和备份统计）
  private logToLocal(eventName: string, params: EventParams) {
    try {
      const logEntry = {
        timestamp: new Date().toISOString(),
        event: eventName,
        params: params,
        userAgent: navigator.userAgent,
        url: window.location.href
      };

      // 存储到localStorage (保留最近100条记录)
      const logs = JSON.parse(localStorage.getItem('analytics_logs') || '[]');
      logs.push(logEntry);
      
      // 只保留最近100条
      if (logs.length > 100) {
        logs.splice(0, logs.length - 100);
      }
      
      localStorage.setItem('analytics_logs', JSON.stringify(logs));
    } catch (error) {
      console.error('Local logging error:', error);
    }
  }

  // 获取本地统计数据
  getLocalLogs(): any[] {
    try {
      return JSON.parse(localStorage.getItem('analytics_logs') || '[]');
    } catch {
      return [];
    }
  }

  // 清除本地统计数据
  clearLocalLogs() {
    localStorage.removeItem('analytics_logs');
  }
}

// 创建单例实例
const analytics = new Analytics();

// 导出常用的快捷函数
export const trackGotoBuy = (params: {
  product_id?: string;
  product_name?: string;
  category?: string;
  price?: string;
  color?: string;
  url?: string;
  source?: string;
}) => analytics.gotobuy(params);

export const trackProductClick = (params: {
  product_id?: string;
  product_name?: string;
  category?: string;
  source?: string;
}) => analytics.productClick(params);

export const trackColorChange = (params: {
  product_id?: string;
  product_name?: string;
  from_color?: string;
  to_color?: string;
}) => analytics.colorChange(params);

export const trackPageView = (pageName: string, additionalParams: EventParams = {}) => 
  analytics.pageView(pageName, additionalParams);

export default analytics; 