import React from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';
import { devices } from '../../styles/breakpoints';

const FooterWrapper = styled.footer`
  width: 100%;
  background: #000;
`;

// 底部导航区域
const FooterNavigation = styled.div`
  margin: 0 53px;
  padding: 25px 0;
  border-bottom: 1px solid #A3A3A3;

  ${devices.laptop} {
    margin: 0 106px;
    padding: 55px 0;
  }
`;

const NavContent = styled.div`
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 25px;

  ${devices.laptop} {
    flex-direction: row;
    gap: 63px;
    align-items: center;
  }
`;

const FooterLogo = styled.div`
  display: flex;
  align-items: center;
  img {
    height: 15px;
    width: auto;

    ${devices.laptop} {
      height: 31px;
    }
  }
`;

const FooterNavLinks = styled.nav`
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 24px;

  ${devices.tablet} {
    gap: 45px;
    justify-content: center;
  }

  ${devices.desktop} {
    gap: 60px;
    justify-content: center;
  }
`;

const NavLink = styled(Link)`
  color: #fff;
  font-size: 16px;
  text-decoration: none;
  font-weight: 400;
  transition: color 0.3s;

  // &:hover {
  //   color: #573274;
  // }
`;

const FooterContent = styled.div`
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;

  ${devices.laptop} {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    padding: 45px 106px;
  }
`;

const LeftSection = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;

  ${devices.laptop} {
    flex-direction: row;
    align-items: center;
    gap: 40px;
  }
`;

const Copyright = styled.div`
  color: #fff;
  font-size: 13px;
  white-space: nowrap;
  font-weight: 200;
`;

const LegalLinks = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px 24px;
  
  ${devices.laptop} {
    flex-wrap: nowrap;
    gap: 24px;
  }

  a {
    color: #fff;
    font-size: 14px;
    text-decoration: none;
    white-space: nowrap;
    transition: color 0.3s;
    font-weight: 200;

    &:hover {
      color: #8B5CF6;
    }
  }
`;

const SocialLinks = styled.div`
  display: flex;
  gap: 16px;
  
  a {
    display: block;
    width: 24px;
    height: 24px;
    background: #D1D5DB;
    border-radius: 4px;
    transition: opacity 0.3s;

    &:hover {
      opacity: 0.8;
    }
  }
`;

const Footer: React.FC = () => {
  return (
    <FooterWrapper>
      {/* 底部导航区域 */}
      <FooterNavigation>
        <NavContent>
          <FooterLogo>
            <img src="/images/footer_logo.png" alt="Ovutek" />
          </FooterLogo>
          
          <FooterNavLinks>
            <NavLink to="/scales">Scales</NavLink>
            <NavLink to="/bp-monitors">BP Monitors</NavLink>
            <NavLink to="/app">App</NavLink>
            <NavLink to="/support">Support</NavLink>
            <NavLink to="/about">About</NavLink>
          </FooterNavLinks>
        </NavContent>
      </FooterNavigation>

      {/* 原有的底部内容 */}
      <FooterContent>
        <LeftSection>
          <Copyright>
            © 2025 Ovutek All rights reserved.
          </Copyright>
          
          <LegalLinks>
            <Link to="/privacy">Privacy Statement</Link>
            <Link to="/agreement">Terms of User</Link>
          </LegalLinks>
        </LeftSection>

        {/* <SocialLinks>
          <a href="https://instagram.com" target="_blank" rel="noopener noreferrer" />
          <a href="https://facebook.com" target="_blank" rel="noopener noreferrer" />
          <a href="https://twitter.com" target="_blank" rel="noopener noreferrer" />
          <a href="https://tiktok.com" target="_blank" rel="noopener noreferrer" />
          <a href="https://linkedin.com" target="_blank" rel="noopener noreferrer" />
          <a href="https://youtube.com" target="_blank" rel="noopener noreferrer" />
        </SocialLinks> */}
      </FooterContent>
    </FooterWrapper>
  );
};

export default Footer; 