import React from 'react';
import styled from 'styled-components';
import Banner from '../components/common/Banner';
import ProductPromotion from '../components/common/ProductPromotion';
import Gallery from '../components/common/Gallery';
import { 
  scalesFirstSection, 
  scalesSecondSection, 
  scalePromotionalImages,
  scalesBannerItems,
  scalesFirstSectionTitle,
  scalesFirstSectionSubtitle,
  scalesSecondSectionTitle,
  scalesSecondSectionSubtitle
} from '../data/products';
import { devices } from '../styles/breakpoints';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;

  ${devices.tablet} {
    padding-top: 60px;
  }

  ${devices.desktop} {
    padding-top: 80px;
  }
`;

const ProductsWrapper = styled.div`
  padding-top: 0;
  .scales-first-section {
    margin-top: 20px !important;
  }
`;


const PromotionalHero = styled.section`
  display: flex;
  flex-direction: row;
  padding: 40px 20px 0 20px;
  margin-bottom: 0;
  margin-left: auto;
  margin-right: auto;
  justify-content: space-between;

  ${devices.tablet} {
    padding: 0;
    padding-top: 156.75px;
    margin-left: 120px;
    justify-content: space-between;
  }

  ${devices.desktop} {
    padding: 0;
    padding-top: 209px;
    margin-left: 160px;
    justify-content: space-between;
  }

  .text-content {
    flex: 1;

    ${devices.tablet} {
      padding-top: 93.75px;
      text-align: left;
    }

    ${devices.desktop} {
      padding-top: 125px;
      text-align: left;
    }
  }

  .image-content {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: flex-end;

    img {
      width: 100%;
      height: auto;
      max-width: 785px;
      object-fit: contain;
      margin-right: 0;
    }
  }
`;

const ComparisonSection = styled.section`
  text-align: center;
  width: 1600px;
  overflow-x: auto;
  margin: 20px;
  ${devices.tablet} {
    width: auto;
    overflow-x: none;
    margin: 0 116.25px;
  }

  ${devices.desktop} {
    width: auto;
    overflow-x: none;
    margin: 0 155px;
  }

  img {
    border-radius: 10px;
    width: 100%;
    height: auto;
    object-fit: cover;
  }
`;

const Scales: React.FC = () => {

  return (
    <PageWrapper>
      <ProductsWrapper>
        <Banner bannerGroups={scalesBannerItems} showArrows={false} />
        <PromotionalHero>
          <div className="text-content">
            <img src="/images/Scales/scales_hero_product_text.png" alt="OVUTEK Scale Product" />
          </div>
          <div className="image-content">
            <img src="/images/Scales/scales_hero_product.png" alt="OVUTEK Scale Product" />
          </div>
        </PromotionalHero>

        <ProductPromotion
          className="scales-first-section"
          title={scalesFirstSectionTitle}
          subtitle={scalesFirstSectionSubtitle}
          products={scalesFirstSection}
          onProductClick={(product) => console.log('Scale product clicked:', product)}
          onShopNowClick={(product) => console.log('Shop now clicked:', product)}
        />

        <ProductPromotion
          title={scalesSecondSectionTitle}
          subtitle={scalesSecondSectionSubtitle}
          products={scalesSecondSection}
          onProductClick={(product) => console.log('Scale product clicked:', product)}
          onShopNowClick={(product) => console.log('Shop now clicked:', product)}
        />

        <ComparisonSection>
          <img src="/images/Scales/scales_comparison.png" alt="Comparison" />
        </ComparisonSection>

        <Gallery
          cards={scalePromotionalImages}
          onCardClick={(card, index) => console.log('Card clicked:', card, index)}
        />


      </ProductsWrapper>
    </PageWrapper>
  );
};

export default Scales; 